window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-4ef6e22a900b8c92"]={"versions": [{"id": "FIG-4ef6e22a900b8c92", "releases": ["R3.2.3", "R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> Architekturschichten- und Datenflussmodell (AUTOSAR Classic Platform BSW Communication Stack) mit PDU-Typisierung und Routing-Pfaden.\n</li><li><strong>Technischer Zweck &amp; funktionale Einordnung:</strong> Spezifikation des Signal- und PDU-Flusses im Kommunikations-Cluster des AUTOSAR System Templates. Das Diagramm definiert die vertikale Kapselung, die Abstraktionsebenen (Services, Hardware Abstraction, Drivers) sowie die Transformations- und Verteilungsstufen von anwendungsspezifischen Signalen über Interaktions-Layer-PDUs (I-PDUs), Netzwerk-PDUs (N-PDUs) bis hin zu Data-Link-PDUs (L-PDUs) über heterogene Bussysteme (FlexRay, CAN, LIN).\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Schichten &amp; BSW-Module (Akteure)</h5>\n<ul class=\"fig-list\"><li><strong>Application / RTE:</strong> Oberste Abstraktionsebene; Übergabe typisierter Signale (<code>Signals</code>) an den BSW-Kommunikationsstack.\n</li><li><strong>Communication Services (Service Layer):</strong>\n<ul class=\"fig-list\"><li><code>AUTOSAR COM</code>: Signal-to-PDU-Mapping, Signal-Packing/Unpacking, Signal-Filterung, Cyclic/Event-basiertes Senden.\n</li><li><code>IPDU Multiplexer (IpduM)</code>: Multiplexen/Demultiplexen dynamischer PDU-Layouts (Selector-Field-Auswertung).\n</li><li><code>Diagnostic Communication Manager (DCM)</code>: Verarbeitung von UDS-/OBD-Diagnoseanfragen; Bereitstellung/Empfang von <code>DCM-I-PDU</code>.\n</li><li><code>PDU Router (PduR)</code>: Zentraler, protokollunabhängiger Routing-Knotenpunkt für I-PDUs (1:1, 1:n, Gateway-Routing zwischen TPs und Interfaces).\n</li><li><code>Complex Device Driver (CDD)</code>: Bypass- und Spezialmodule; oberer CDD nutzt <code>USER-DEFINED-I-PDU</code>, unterer CDD bindet direkt über <code>USER-DEFINED-PDU</code> an Interfaces an.\n</li><li><code>Network Management (NM Module)</code>: Generische/busspezifische NM-Module (<code>FrNm</code>, <code>CanNm</code>, <code>LinNm</code>); aggregiert <code>NM-PDU</code> und nimmt <code>UserData NM-PDU</code> auf.\n</li><li><strong>Transportprotokoll-Module:</strong> <code>FlexRay Tp (FrTp)</code>, <code>CAN Tp (CanTp)</code>, <code>J1939Tp</code>; Segmentierung/Reassemblierung größerer I-PDUs in N-PDUs.\n</li></ul>\n</li><li><strong>Communication HW Abstraction:</strong>\n<ul class=\"fig-list\"><li><code>FlexRay Interface (FrIf)</code>, <code>CAN Interface (CanIf)</code>, <code>LIN Interface (LinIf, incl. LIN TP)</code>: Abstraktion der Controller/Transceiver-Hardware, PDU-Kanalzuordnung und PDU-ID-Übersetzung.\n</li></ul>\n</li><li><strong>Communication Drivers (MCAL Layer):</strong>\n<ul class=\"fig-list\"><li><code>FlexRay Driver (Fr)</code>, <code>CAN Driver (Can)</code>, <code>LIN Low Level Driver (Lin)</code>: Direkte Hardware-Register-Ansteuerung und Mailbox-Handling.\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">PDU-Klassifikationen &amp; Stereotypen (System Template / Metamodell)</h5>\n<ul class=\"fig-list\"><li><code>Signals</code>: Rohdaten-Payloads der Software Components (SWCs) an der RTE-Schnittstelle.\n</li><li><code>I-SIGNAL-I-PDU</code>: PDU-Container im COM zur Bündelung von <code>ISignal</code> und <code>ISignalGroup</code>.\n</li><li><code>I-SIGNAL-I-PDU (Multiplexed part)</code>: Dynamischer Signal-Teil, der an den <code>IpduM</code> übergeben wird.\n</li><li><code>MULTIPLEXED-I-PDU</code>: Gesamte PDU nach Zusammenbau durch <code>IpduM</code> (statischer Anteil + Multiplex-Payload).\n</li><li><code>DCM-I-PDU</code>: Unsegmentierte Diagnose-Payloads (UDS-Frames).\n</li><li><code>UserData NM-PDU</code>: Payload-Daten aus dem COM, die in die Netzwerk-Management-Nachricht eingebettet werden.\n</li><li><code>I-PDU</code>: Interaktionsschicht-PDU; neutrale Transporteinheit auf <code>PduR</code>-Ebene.\n</li><li><code>N-PDU</code>: Network-PDU; segmentierte Transportprotokoll-Einheiten (FrTp, CanTp, J1939Tp).\n</li><li><code>NM-PDU</code>: Management-Frames der NM-State-Machine, direkt in Hardware-Interfaces gespeist.\n</li><li><code>USER-DEFINED-I-PDU</code> / <code>USER-DEFINED-PDU</code>: Proprietäre oder zeitkritische PDU-Formate für CDD-Anbindungen.\n</li><li><code>L-PDU</code>: Link-Layer-PDU (Hardware-Frame, z. B. CAN-Frame mit CAN-ID und DLC) zwischen Interface und MCAL-Treiber.\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<h5 class=\"fig-section-h5\">Transmit-Pfade (TX)</h5>\n<ol class=\"fig-list\"><li><strong>Unsegmentierter Standard-Signalpfad:</strong>\n<ul class=\"fig-list\"><li>RTE übergibt Signalwerte an <code>AUTOSAR COM</code> (<code>Com_SendSignal</code>).\n</li><li>COM packt Signale in die zugehörige <code>I-SIGNAL-I-PDU</code> und triggert den <code>PduR</code> (<code>PduR_ComTransmit</code>).\n</li><li><code>PduR</code> leitet die <code>I-PDU</code> deterministisch an das Ziel-Interface weiter (z. B. <code>CanIf_Transmit</code>).\n</li><li>Das Interface kapselt die Payload in eine <code>L-PDU</code> und übergibt an den Treiber (<code>Can_Write</code>).\n</li><li>Rückmeldung erfolgt asynchron über Tx-Confirmation-Callbacks von MCAL über Interface und PduR bis COM.\n</li></ul>\n</li><li><strong>Multiplex-Pfad (IpduM):</strong>\n<ul class=\"fig-list\"><li>COM separiert statische und dynamische Signale; dynamische Teile gehen als <code>I-SIGNAL-I-PDU (Multiplexed part)</code> an <code>IpduM</code>.\n</li><li><code>IpduM</code> kombiniert den Selektor-Wert mit dem entsprechenden dynamischen Signal-Layout zu einer <code>MULTIPLEXED-I-PDU</code> und übergibt an <code>PduR</code>.\n</li></ul>\n</li><li><strong>Segmentierter TP-Pfad (Diagnose / Large Data):</strong>\n<ul class=\"fig-list\"><li>DCM übergibt <code>DCM-I-PDU</code> (&gt; 8 Bytes bei Classic CAN) an <code>PduR</code> (<code>PduR_DcmTransmit</code>).\n</li><li><code>PduR</code> routet an TP-Modul (<code>CanTp_Transmit</code>, <code>FrTp_Transmit</code>).\n</li><li>TP segmentiert die PDU (First Frame, Flow Control, Consecutive Frames) in einzelne <code>N-PDUs</code> und übergibt diese getaktet via Interface an den Treiber. Puffer-Handling erfolgt über Callback-Abfragen (<code>PduR_ProvideTxBuffer</code> / <code>CopyTxData</code>).\n</li></ul>\n</li><li><strong>Netzwerk-Management &amp; User-Data:</strong>\n<ul class=\"fig-list\"><li>NM-Statusmaschine generiert zyklisch/eventbasiert <code>NM-PDUs</code>.\n</li><li>Optional werden <code>UserData NM-PDUs</code> synchron aus dem COM via <code>PduR</code> beigezogen und im Bus-Interface als direkte <code>NM-PDU</code> gesendet.\n</li></ul>\n</li><li><strong>CDD-Bypass:</strong>\n<ul class=\"fig-list\"><li>CDD umgeht wahlweise den COM-Stack (via <code>USER-DEFINED-I-PDU</code> über den PduR) oder den PduR komplett (via <code>USER-DEFINED-PDU</code> direkt auf Interface-Ebene), um Latenzen zu minimieren oder non-AUTOSAR-Frames zu verarbeiten.\n</li></ul>\n</li></ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>PDU-ID-Mapping &amp; Entkopplung:</strong> Module referenzieren PDUs über numerische Handles (<code>PduIdType</code>). Jedes Modul (<code>Com</code>, <code>PduR</code>, <code>CanIf</code>, <code>CanTp</code>) besitzt separate lokale ID-Namensräume. In der ARXML-Systembeschreibung müssen <code>SourcePduId</code> und <code>TargetPduId</code> in den PduR-Routing-Tabellen strikt aufeinander abgestimmt sein.\n</li><li><strong>PduR-Beschränkung:</strong> Der <code>PduR</code> ist zustandslos bezüglich der PDU-Payload; er transformiert, konvertiert oder verändert keine Dateninhalte, sondern routet ausschließlich Zeiger und Längen (<code>PduInfoType</code>).\n</li><li><strong>Zero-Copy &amp; Pufferarchitektur:</strong>\n<ul class=\"fig-list\"><li>Auf Interface-Ebene (<code>CanIf</code>, <code>FrIf</code>) gilt standardmäßig direkte Puffer-Referenzierung ohne Entkopplungsspeicher (ausgenommen Gateway-FIFO oder Trigger-Transmit-Puffer).\n</li><li>Bei TP-Kommunikation müssen Pufferanforderungen (<code>ProvideTxBuffer</code> / <code>CopyTxData</code>, <code>CopyRxData</code>) reentrant implementiert sein.\n</li></ul>\n</li><li><strong>IPDU-Multiplexing-Overhead:</strong> Verwendung von <code>IpduM</code> erfordert deterministisches Timing, da COM und IpduM PDU-Zustände synchronisieren müssen; Selector-Kollisionen müssen im System-Design ausgeschlossen werden.\n</li><li><strong>CDD-Entwickler-Richtlinie:</strong> Wird ein CDD unterhalb des <code>PduR</code> angebunden (<code>USER-DEFINED-PDU</code>), muss der CDD die AUTOSAR-kompatiblen Callback-Signaturen des jeweiligen Interfaces (<code>&lt;Bus&gt;If_RxIndication</code>, <code>&lt;Bus&gt;If_TxConfirmation</code>) exakt implementieren.\n</li></ul>"}, {"id": "FIG-abe1d38b0d5f1fa2", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> Architekturschichten- und Datenflussmodell (AUTOSAR Classic Platform BSW Communication Stack) mit PDU-Typisierung und Routing-Pfaden.\n</li><li><strong>Technischer Zweck &amp; funktionale Einordnung:</strong> Spezifikation des Signal- und PDU-Flusses im Kommunikations-Cluster des AUTOSAR System Templates. Das Diagramm definiert die vertikale Kapselung, die Abstraktionsebenen (Services, Hardware Abstraction, Drivers) sowie die Transformations- und Verteilungsstufen von anwendungsspezifischen Signalen über Interaktions-Layer-PDUs (I-PDUs), Netzwerk-PDUs (N-PDUs) bis hin zu Data-Link-PDUs (L-PDUs) über heterogene Bussysteme (FlexRay, CAN, LIN).\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Schichten &amp; BSW-Module (Akteure)</h5>\n<ul class=\"fig-list\"><li><strong>Application / RTE:</strong> Oberste Abstraktionsebene; Übergabe typisierter Signale (<code>Signals</code>) an den BSW-Kommunikationsstack.\n</li><li><strong>Communication Services (Service Layer):</strong>\n<ul class=\"fig-list\"><li><code>AUTOSAR COM</code>: Signal-to-PDU-Mapping, Signal-Packing/Unpacking, Signal-Filterung, Cyclic/Event-basiertes Senden.\n</li><li><code>IPDU Multiplexer (IpduM)</code>: Multiplexen/Demultiplexen dynamischer PDU-Layouts (Selector-Field-Auswertung).\n</li><li><code>Diagnostic Communication Manager (DCM)</code>: Verarbeitung von UDS-/OBD-Diagnoseanfragen; Bereitstellung/Empfang von <code>DCM-I-PDU</code>.\n</li><li><code>PDU Router (PduR)</code>: Zentraler, protokollunabhängiger Routing-Knotenpunkt für I-PDUs (1:1, 1:n, Gateway-Routing zwischen TPs und Interfaces).\n</li><li><code>Complex Device Driver (CDD)</code>: Bypass- und Spezialmodule; oberer CDD nutzt <code>USER-DEFINED-I-PDU</code>, unterer CDD bindet direkt über <code>USER-DEFINED-PDU</code> an Interfaces an.\n</li><li><code>Network Management (NM Module)</code>: Generische/busspezifische NM-Module (<code>FrNm</code>, <code>CanNm</code>, <code>LinNm</code>); aggregiert <code>NM-PDU</code> und nimmt <code>UserData NM-PDU</code> auf.\n</li><li><strong>Transportprotokoll-Module:</strong> <code>FlexRay Tp (FrTp)</code>, <code>CAN Tp (CanTp)</code>, <code>J1939Tp</code>; Segmentierung/Reassemblierung größerer I-PDUs in N-PDUs.\n</li></ul>\n</li><li><strong>Communication HW Abstraction:</strong>\n<ul class=\"fig-list\"><li><code>FlexRay Interface (FrIf)</code>, <code>CAN Interface (CanIf)</code>, <code>LIN Interface (LinIf, incl. LIN TP)</code>: Abstraktion der Controller/Transceiver-Hardware, PDU-Kanalzuordnung und PDU-ID-Übersetzung.\n</li></ul>\n</li><li><strong>Communication Drivers (MCAL Layer):</strong>\n<ul class=\"fig-list\"><li><code>FlexRay Driver (Fr)</code>, <code>CAN Driver (Can)</code>, <code>LIN Low Level Driver (Lin)</code>: Direkte Hardware-Register-Ansteuerung und Mailbox-Handling.\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">PDU-Klassifikationen &amp; Stereotypen (System Template / Metamodell)</h5>\n<ul class=\"fig-list\"><li><code>Signals</code>: Rohdaten-Payloads der Software Components (SWCs) an der RTE-Schnittstelle.\n</li><li><code>I-SIGNAL-I-PDU</code>: PDU-Container im COM zur Bündelung von <code>ISignal</code> und <code>ISignalGroup</code>.\n</li><li><code>I-SIGNAL-I-PDU (Multiplexed part)</code>: Dynamischer Signal-Teil, der an den <code>IpduM</code> übergeben wird.\n</li><li><code>MULTIPLEXED-I-PDU</code>: Gesamte PDU nach Zusammenbau durch <code>IpduM</code> (statischer Anteil + Multiplex-Payload).\n</li><li><code>DCM-I-PDU</code>: Unsegmentierte Diagnose-Payloads (UDS-Frames).\n</li><li><code>UserData NM-PDU</code>: Payload-Daten aus dem COM, die in die Netzwerk-Management-Nachricht eingebettet werden.\n</li><li><code>I-PDU</code>: Interaktionsschicht-PDU; neutrale Transporteinheit auf <code>PduR</code>-Ebene.\n</li><li><code>N-PDU</code>: Network-PDU; segmentierte Transportprotokoll-Einheiten (FrTp, CanTp, J1939Tp).\n</li><li><code>NM-PDU</code>: Management-Frames der NM-State-Machine, direkt in Hardware-Interfaces gespeist.\n</li><li><code>USER-DEFINED-I-PDU</code> / <code>USER-DEFINED-PDU</code>: Proprietäre oder zeitkritische PDU-Formate für CDD-Anbindungen.\n</li><li><code>L-PDU</code>: Link-Layer-PDU (Hardware-Frame, z. B. CAN-Frame mit CAN-ID und DLC) zwischen Interface und MCAL-Treiber.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<h5 class=\"fig-section-h5\">Transmit-Pfade (TX)</h5>\n<ol class=\"fig-list\"><li><strong>Unsegmentierter Standard-Signalpfad:</strong>\n<ul class=\"fig-list\"><li>RTE übergibt Signalwerte an <code>AUTOSAR COM</code> (<code>Com_SendSignal</code>).\n</li><li>COM packt Signale in die zugehörige <code>I-SIGNAL-I-PDU</code> und triggert den <code>PduR</code> (<code>PduR_ComTransmit</code>).\n</li><li><code>PduR</code> leitet die <code>I-PDU</code> deterministisch an das Ziel-Interface weiter (z. B. <code>CanIf_Transmit</code>).\n</li><li>Das Interface kapselt die Payload in eine <code>L-PDU</code> und übergibt an den Treiber (<code>Can_Write</code>).\n</li><li>Rückmeldung erfolgt asynchron über Tx-Confirmation-Callbacks von MCAL über Interface und PduR bis COM.\n</li></ul>\n</li><li><strong>Multiplex-Pfad (IpduM):</strong>\n<ul class=\"fig-list\"><li>COM separiert statische und dynamische Signale; dynamische Teile gehen als <code>I-SIGNAL-I-PDU (Multiplexed part)</code> an <code>IpduM</code>.\n</li><li><code>IpduM</code> kombiniert den Selektor-Wert mit dem entsprechenden dynamischen Signal-Layout zu einer <code>MULTIPLEXED-I-PDU</code> und übergibt an <code>PduR</code>.\n</li></ul>\n</li><li><strong>Segmentierter TP-Pfad (Diagnose / Large Data):</strong>\n<ul class=\"fig-list\"><li>DCM übergibt <code>DCM-I-PDU</code> (&gt; 8 Bytes bei Classic CAN) an <code>PduR</code> (<code>PduR_DcmTransmit</code>).\n</li><li><code>PduR</code> routet an TP-Modul (<code>CanTp_Transmit</code>, <code>FrTp_Transmit</code>).\n</li><li>TP segmentiert die PDU (First Frame, Flow Control, Consecutive Frames) in einzelne <code>N-PDUs</code> und übergibt diese getaktet via Interface an den Treiber. Puffer-Handling erfolgt über Callback-Abfragen (<code>PduR_ProvideTxBuffer</code> / <code>CopyTxData</code>).\n</li></ul>\n</li><li><strong>Netzwerk-Management &amp; User-Data:</strong>\n<ul class=\"fig-list\"><li>NM-Statusmaschine generiert zyklisch/eventbasiert <code>NM-PDUs</code>.\n</li><li>Optional werden <code>UserData NM-PDUs</code> synchron aus dem COM via <code>PduR</code> beigezogen und im Bus-Interface als direkte <code>NM-PDU</code> gesendet.\n</li></ul>\n</li><li><strong>CDD-Bypass:</strong>\n<ul class=\"fig-list\"><li>CDD umgeht wahlweise den COM-Stack (via <code>USER-DEFINED-I-PDU</code> über den PduR) oder den PduR komplett (via <code>USER-DEFINED-PDU</code> direkt auf Interface-Ebene), um Latenzen zu minimieren oder non-AUTOSAR-Frames zu verarbeiten.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>PDU-ID-Mapping &amp; Entkopplung:</strong> Module referenzieren PDUs über numerische Handles (<code>PduIdType</code>). Jedes Modul (<code>Com</code>, <code>PduR</code>, <code>CanIf</code>, <code>CanTp</code>) besitzt separate lokale ID-Namensräume. In der ARXML-Systembeschreibung müssen <code>SourcePduId</code> und <code>TargetPduId</code> in den PduR-Routing-Tabellen strikt aufeinander abgestimmt sein.\n</li><li><strong>PduR-Beschränkung:</strong> Der <code>PduR</code> ist zustandslos bezüglich der PDU-Payload; er transformiert, konvertiert oder verändert keine Dateninhalte, sondern routet ausschließlich Zeiger und Längen (<code>PduInfoType</code>).\n</li><li><strong>Zero-Copy &amp; Pufferarchitektur:</strong>\n<ul class=\"fig-list\"><li>Auf Interface-Ebene (<code>CanIf</code>, <code>FrIf</code>) gilt standardmäßig direkte Puffer-Referenzierung ohne Entkopplungsspeicher (ausgenommen Gateway-FIFO oder Trigger-Transmit-Puffer).\n</li><li>Bei TP-Kommunikation müssen Pufferanforderungen (<code>ProvideTxBuffer</code> / <code>CopyTxData</code>, <code>CopyRxData</code>) reentrant implementiert sein.\n</li></ul>\n</li><li><strong>IPDU-Multiplexing-Overhead:</strong> Verwendung von <code>IpduM</code> erfordert deterministisches Timing, da COM und IpduM PDU-Zustände synchronisieren müssen; Selector-Kollisionen müssen im System-Design ausgeschlossen werden.\n</li><li><strong>CDD-Entwickler-Richtlinie:</strong> Wird ein CDD unterhalb des <code>PduR</code> angebunden (<code>USER-DEFINED-PDU</code>), muss der CDD die AUTOSAR-kompatiblen Callback-Signaturen des jeweiligen Interfaces (<code>&lt;Bus&gt;If_RxIndication</code>, <code>&lt;Bus&gt;If_TxConfirmation</code>) exakt implementieren.\n</li></ul>"}, {"id": "FIG-adbd9d3506f20d83", "releases": ["R4.2.2", "R24-11", "R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> Architekturschichten- und Datenflussmodell (AUTOSAR Classic Platform BSW Communication Stack) mit PDU-Typisierung und Routing-Pfaden.\n</li><li><strong>Technischer Zweck &amp; funktionale Einordnung:</strong> Spezifikation des Signal- und PDU-Flusses im Kommunikations-Cluster des AUTOSAR System Templates. Das Diagramm definiert die vertikale Kapselung, die Abstraktionsebenen (Services, Hardware Abstraction, Drivers) sowie die Transformations- und Verteilungsstufen von anwendungsspezifischen Signalen über Interaktions-Layer-PDUs (I-PDUs), Netzwerk-PDUs (N-PDUs) bis hin zu Data-Link-PDUs (L-PDUs) über heterogene Bussysteme (FlexRay, CAN, LIN).\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Schichten &amp; BSW-Module (Akteure)</h5>\n<ul class=\"fig-list\"><li><strong>Application / RTE:</strong> Oberste Abstraktionsebene; Übergabe typisierter Signale (<code>Signals</code>) an den BSW-Kommunikationsstack.\n</li><li><strong>Communication Services (Service Layer):</strong>\n<ul class=\"fig-list\"><li><code>AUTOSAR COM</code>: Signal-to-PDU-Mapping, Signal-Packing/Unpacking, Signal-Filterung, Cyclic/Event-basiertes Senden.\n</li><li><code>IPDU multiplexer (IpduM)</code>: Multiplexen/Demultiplexen dynamischer PDU-Layouts sowie Container-PDU-Handling.\n</li><li><code>SecOC (Secure Onboard Communication)</code>: Kryptografische Absicherung von PDUs (Authentifizierung und Frischeprüfung); angebunden an den <code>PDU Router</code>.\n</li><li><code>Diagnostic Communication Manager (DCM)</code>: Verarbeitung von UDS-/OBD-Diagnoseanfragen; Bereitstellung/Empfang von <code>DCM-I-PDU</code>.\n</li><li><code>PDU Router (PduR)</code>: Zentraler, protokollunabhängiger Routing-Knotenpunkt für I-PDUs (1:1, 1:n, Gateway-Routing zwischen TPs, Interfaces, SecOC und IpduM).\n</li><li><code>Complex Device Driver (CDD)</code>: Bypass- und Spezialmodule; oberer CDD nutzt <code>USER-DEFINED-I-PDU</code>, unterer CDD bindet direkt über <code>USER-DEFINED-PDU</code> an Interfaces an.\n</li><li><code>Network Management (NM Module)</code>: Generische/busspezifische NM-Module (<code>FrNm</code>, <code>CanNm</code>, <code>LinNm</code>); aggregiert <code>NM-PDU</code> und nimmt <code>UserData NM-PDU</code> auf.\n</li><li><strong>Transportprotokoll-Module:</strong> <code>FlexRay Tp (FrTp)</code>, <code>CAN Tp (CanTp)</code>, <code>J1939Tp</code>; Segmentierung/Reassemblierung größerer I-PDUs in N-PDUs.\n</li></ul>\n</li><li><strong>Communication HW Abstraction:</strong>\n<ul class=\"fig-list\"><li><code>FlexRay Interface (FrIf)</code>, <code>CAN Interface (CanIf)</code>, <code>LIN Interface (LinIf, incl. LIN TP)</code>: Abstraktion der Controller/Transceiver-Hardware, PDU-Kanalzuordnung und PDU-ID-Übersetzung.\n</li></ul>\n</li><li><strong>Communication Drivers (MCAL Layer):</strong>\n<ul class=\"fig-list\"><li><code>FlexRay Driver (Fr)</code>, <code>CAN Driver (Can)</code>, <code>LIN Low Level Driver (Lin)</code>: Direkte Hardware-Register-Ansteuerung und Mailbox-Handling.\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">PDU-Klassifikationen &amp; Stereotypen (System Template / Metamodell)</h5>\n<ul class=\"fig-list\"><li><code>Signals</code>: Rohdaten-Payloads der Software Components (SWCs) an der RTE-Schnittstelle.\n</li><li><code>I-SIGNAL-I-PDU</code>: PDU-Container zur Bündelung von <code>ISignal</code> und <code>ISignalGroup</code>; Schnittstelle zwischen COM, PDU Router, IpduM und SecOC.\n</li><li><code>CONTAINER-I-PDU</code>: PDU-Container zur Bündelung mehrerer PDUs für Transport und Multiplexing via IpduM.\n</li><li><code>MULTIPLEXED-I-PDU</code>: Gesamte PDU nach Zusammenbau durch <code>IpduM</code> (statischer Anteil + Multiplex-Payload).\n</li><li><code>SECURED-I-PDU</code>: Durch SecOC kryptografisch geschützte PDU (Payload inklusive Authentifikationsinformation / MAC und Freshness Value).\n</li><li><code>DCM-I-PDU</code>: Unsegmentierte Diagnose-Payloads (UDS-Frames).\n</li><li><code>UserData NM-PDU</code>: Payload-Daten aus dem COM, die in die Netzwerk-Management-Nachricht eingebettet werden.\n</li><li><code>I-PDU</code>: Interaktionsschicht-PDU; neutrale Transporteinheit auf <code>PduR</code>-Ebene.\n</li><li><code>N-PDU</code>: Network-PDU; segmentierte Transportprotokoll-Einheiten (FrTp, CanTp, J1939Tp).\n</li><li><code>NM-PDU</code>: Management-Frames der NM-State-Machine, direkt in Hardware-Interfaces gespeist.\n</li><li><code>USER-DEFINED-I-PDU</code> / <code>USER-DEFINED-PDU</code>: Proprietäre oder zeitkritische PDU-Formate für CDD-Anbindungen.\n</li><li><code>L-PDU</code>: Link-Layer-PDU (Hardware-Frame, z. B. CAN-Frame mit CAN-ID und DLC) zwischen Interface und MCAL-Treiber.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<h5 class=\"fig-section-h5\">Transmit-Pfade (TX)</h5>\n<ol class=\"fig-list\"><li><strong>Unsegmentierter Standard-Signalpfad:</strong>\n<ul class=\"fig-list\"><li>RTE übergibt Signalwerte an <code>AUTOSAR COM</code> (<code>Com_SendSignal</code>).\n</li><li>COM packt Signale in die zugehörige <code>I-SIGNAL-I-PDU</code> und triggert den <code>PduR</code> (<code>PduR_ComTransmit</code>).\n</li><li><code>PduR</code> leitet die <code>I-PDU</code> deterministisch an das Ziel-Interface weiter (z. B. <code>CanIf_Transmit</code>).\n</li><li>Das Interface kapselt die Payload in eine <code>L-PDU</code> und übergibt an den Treiber (<code>Can_Write</code>).\n</li><li>Rückmeldung erfolgt asynchron über Tx-Confirmation-Callbacks von MCAL über Interface und PduR bis COM.\n</li></ul>\n</li><li><strong>Multiplex-Pfad (IpduM):</strong>\n<ul class=\"fig-list\"><li>COM separiert statische und dynamische Signale; dynamische Teile gehen als <code>I-SIGNAL-I-PDU (Multiplexed part)</code> an <code>IpduM</code>.\n</li><li><code>IpduM</code> kombiniert den Selektor-Wert mit dem entsprechenden dynamischen Signal-Layout zu einer <code>MULTIPLEXED-I-PDU</code> und übergibt an <code>PduR</code>.\n</li></ul>\n</li><li><strong>Segmentierter TP-Pfad (Diagnose / Large Data):</strong>\n<ul class=\"fig-list\"><li>DCM übergibt <code>DCM-I-PDU</code> (&gt; 8 Bytes bei Classic CAN) an <code>PduR</code> (<code>PduR_DcmTransmit</code>).\n</li><li><code>PduR</code> routet an TP-Modul (<code>CanTp_Transmit</code>, <code>FrTp_Transmit</code>).\n</li><li>TP segmentiert die PDU (First Frame, Flow Control, Consecutive Frames) in einzelne <code>N-PDUs</code> und übergibt diese getaktet via Interface an den Treiber. Puffer-Handling erfolgt über Callback-Abfragen (<code>PduR_ProvideTxBuffer</code> / <code>CopyTxData</code>).\n</li></ul>\n</li><li><strong>Netzwerk-Management &amp; User-Data:</strong>\n<ul class=\"fig-list\"><li>NM-Statusmaschine generiert zyklisch/eventbasiert <code>NM-PDUs</code>.\n</li><li>Optional werden <code>UserData NM-PDUs</code> synchron aus dem COM via <code>PduR</code> beigezogen und im Bus-Interface als direkte <code>NM-PDU</code> gesendet.\n</li></ul>\n</li><li><strong>CDD-Bypass:</strong>\n<ul class=\"fig-list\"><li>CDD umgeht wahlweise den COM-Stack (via <code>USER-DEFINED-I-PDU</code> über den PduR) oder den PduR komplett (via <code>USER-DEFINED-PDU</code> direkt auf Interface-Ebene), um Latenzen zu minimieren oder non-AUTOSAR-Frames zu verarbeiten.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>PDU-ID-Mapping &amp; Entkopplung:</strong> Module referenzieren PDUs über numerische Handles (<code>PduIdType</code>). Jedes Modul (<code>Com</code>, <code>PduR</code>, <code>CanIf</code>, <code>CanTp</code>) besitzt separate lokale ID-Namensräume. In der ARXML-Systembeschreibung müssen <code>SourcePduId</code> und <code>TargetPduId</code> in den PduR-Routing-Tabellen strikt aufeinander abgestimmt sein.\n</li><li><strong>PduR-Beschränkung:</strong> Der <code>PduR</code> ist zustandslos bezüglich der PDU-Payload; er transformiert, konvertiert oder verändert keine Dateninhalte, sondern routet ausschließlich Zeiger und Längen (<code>PduInfoType</code>).\n</li><li><strong>Zero-Copy &amp; Pufferarchitektur:</strong>\n<ul class=\"fig-list\"><li>Auf Interface-Ebene (<code>CanIf</code>, <code>FrIf</code>) gilt standardmäßig direkte Puffer-Referenzierung ohne Entkopplungsspeicher (ausgenommen Gateway-FIFO oder Trigger-Transmit-Puffer).\n</li><li>Bei TP-Kommunikation müssen Pufferanforderungen (<code>ProvideTxBuffer</code> / <code>CopyTxData</code>, <code>CopyRxData</code>) reentrant implementiert sein.\n</li></ul>\n</li><li><strong>IPDU-Multiplexing-Overhead:</strong> Verwendung von <code>IpduM</code> erfordert deterministisches Timing, da COM und IpduM PDU-Zustände synchronisieren müssen; Selector-Kollisionen müssen im System-Design ausgeschlossen werden.\n</li><li><strong>CDD-Entwickler-Richtlinie:</strong> Wird ein CDD unterhalb des <code>PduR</code> angebunden (<code>USER-DEFINED-PDU</code>), muss der CDD die AUTOSAR-kompatiblen Callback-Signaturen des jeweiligen Interfaces (<code>&lt;Bus&gt;If_RxIndication</code>, <code>&lt;Bus&gt;If_TxConfirmation</code>) exakt implementieren.\n</li></ul>"}, {"id": "FIG-3d188c2c028eaf2c", "releases": ["R4.3.1", "R18-10_R4.4.0_R1.5.0", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> Architekturschichten- und Datenflussmodell (AUTOSAR Classic Platform BSW Communication Stack) mit PDU-Typisierung und Routing-Pfaden.\n</li><li><strong>Technischer Zweck &amp; funktionale Einordnung:</strong> Spezifikation des Signal- und PDU-Flusses im Kommunikations-Cluster des AUTOSAR System Templates. Das Diagramm definiert die vertikale Kapselung, die Abstraktionsebenen (Services, Hardware Abstraction, Drivers) sowie die Transformations- und Verteilungsstufen von anwendungsspezifischen Signalen über Interaktions-Layer-PDUs (I-PDUs), Netzwerk-PDUs (N-PDUs) bis hin zu Data-Link-PDUs (L-PDUs) über heterogene Bussysteme (FlexRay, CAN, LIN).\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Schichten &amp; BSW-Module (Akteure)</h5>\n<ul class=\"fig-list\"><li><strong>Application / RTE:</strong> Oberste Abstraktionsebene; Übergabe typisierter Signale (<code>Signals</code>) an den BSW-Kommunikationsstack.\n</li><li><strong>Communication Services (Service Layer):</strong>\n<ul class=\"fig-list\"><li><code>AUTOSAR COM</code>: Signal-to-PDU-Mapping, Signal-Packing/Unpacking, Signal-Filterung, Cyclic/Event-basiertes Senden.\n</li><li><code>IPDU multiplexer (IpduM)</code>: Multiplexen/Demultiplexen dynamischer PDU-Layouts sowie Container-PDU-Handling.\n</li><li><code>SecOC (Secure Onboard Communication)</code>: Kryptografische Absicherung von PDUs (Authentifizierung und Frischeprüfung); angebunden an den <code>PDU Router</code>.\n</li><li><code>Diagnostic Communication Manager (DCM)</code>: Verarbeitung von UDS-/OBD-Diagnoseanfragen; Bereitstellung/Empfang von <code>DCM-I-PDU</code>.\n</li><li><code>PDU Router (PduR)</code>: Zentraler, protokollunabhängiger Routing-Knotenpunkt für I-PDUs (1:1, 1:n, Gateway-Routing zwischen TPs, Interfaces, SecOC und IpduM).\n</li><li><code>Complex Device Driver (CDD)</code>: Bypass- und Spezialmodule; oberer CDD nutzt <code>USER-DEFINED-I-PDU</code>, unterer CDD bindet direkt über <code>USER-DEFINED-PDU</code> an Interfaces an.\n</li><li><code>Network Management (NM Module)</code>: Generische/busspezifische NM-Module (<code>FrNm</code>, <code>CanNm</code>, <code>LinNm</code>); aggregiert <code>NM-PDU</code> und nimmt <code>UserData NM-PDU</code> auf.\n</li><li><strong>Transportprotokoll-Module:</strong> <code>FlexRay Tp (FrTp)</code>, <code>CAN Tp (CanTp)</code>, <code>J1939Tp</code>; Segmentierung/Reassemblierung größerer I-PDUs in N-PDUs.\n</li></ul>\n</li><li><strong>Communication HW Abstraction:</strong>\n<ul class=\"fig-list\"><li><code>FlexRay Interface (FrIf)</code>, <code>CAN Interface (CanIf)</code>, <code>LIN Interface (LinIf, incl. LIN TP)</code>: Abstraktion der Controller/Transceiver-Hardware, PDU-Kanalzuordnung und PDU-ID-Übersetzung.\n</li></ul>\n</li><li><strong>Communication Drivers (MCAL Layer):</strong>\n<ul class=\"fig-list\"><li><code>FlexRay Driver (Fr)</code>, <code>CAN Driver (Can)</code>, <code>LIN Low Level Driver (Lin)</code>: Direkte Hardware-Register-Ansteuerung und Mailbox-Handling.\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">PDU-Klassifikationen &amp; Stereotypen (System Template / Metamodell)</h5>\n<ul class=\"fig-list\"><li><code>Signals</code>: Rohdaten-Payloads der Software Components (SWCs) an der RTE-Schnittstelle.\n</li><li><code>I-SIGNAL-I-PDU</code>: PDU-Container zur Bündelung von <code>ISignal</code> und <code>ISignalGroup</code>; Schnittstelle zwischen COM, PDU Router, IpduM und SecOC.\n</li><li><code>CONTAINER-I-PDU</code>: PDU-Container zur Bündelung mehrerer PDUs für Transport und Multiplexing via IpduM.\n</li><li><code>MULTIPLEXED-I-PDU</code>: Gesamte PDU nach Zusammenbau durch <code>IpduM</code> (statischer Anteil + Multiplex-Payload).\n</li><li><code>SECURED-I-PDU</code>: Durch SecOC kryptografisch geschützte PDU (Payload inklusive Authentifikationsinformation / MAC und Freshness Value).\n</li><li><code>DCM-I-PDU</code>: Unsegmentierte Diagnose-Payloads (UDS-Frames).\n</li><li><code>UserData NM-PDU</code>: Payload-Daten aus dem COM, die in die Netzwerk-Management-Nachricht eingebettet werden.\n</li><li><code>I-PDU</code>: Interaktionsschicht-PDU; neutrale Transporteinheit auf <code>PduR</code>-Ebene.\n</li><li><code>N-PDU</code>: Network-PDU; segmentierte Transportprotokoll-Einheiten (FrTp, CanTp, J1939Tp).\n</li><li><code>NM-PDU</code>: Management-Frames der NM-State-Machine, direkt in Hardware-Interfaces gespeist.\n</li><li><code>USER-DEFINED-I-PDU</code> / <code>USER-DEFINED-PDU</code>: Proprietäre oder zeitkritische PDU-Formate für CDD-Anbindungen.\n</li><li><code>L-PDU</code>: Link-Layer-PDU (Hardware-Frame, z. B. CAN-Frame mit CAN-ID und DLC) zwischen Interface und MCAL-Treiber.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<h5 class=\"fig-section-h5\">Transmit-Pfade (TX)</h5>\n<ol class=\"fig-list\"><li><strong>Unsegmentierter Standard-Signalpfad:</strong>\n<ul class=\"fig-list\"><li>RTE übergibt Signalwerte an <code>AUTOSAR COM</code> (<code>Com_SendSignal</code>).\n</li><li>COM packt Signale in die zugehörige <code>I-SIGNAL-I-PDU</code> und triggert den <code>PduR</code> (<code>PduR_ComTransmit</code>).\n</li><li><code>PduR</code> leitet die <code>I-PDU</code> deterministisch an das Ziel-Interface weiter (z. B. <code>CanIf_Transmit</code>).\n</li><li>Das Interface kapselt die Payload in eine <code>L-PDU</code> und übergibt an den Treiber (<code>Can_Write</code>).\n</li><li>Rückmeldung erfolgt asynchron über Tx-Confirmation-Callbacks von MCAL über Interface und PduR bis COM.\n</li></ul>\n</li><li><strong>Multiplex-Pfad (IpduM):</strong>\n<ul class=\"fig-list\"><li>COM separiert statische und dynamische Signale; dynamische Teile gehen als <code>I-SIGNAL-I-PDU (Multiplexed part)</code> an <code>IpduM</code>.\n</li><li><code>IpduM</code> kombiniert den Selektor-Wert mit dem entsprechenden dynamischen Signal-Layout zu einer <code>MULTIPLEXED-I-PDU</code> und übergibt an <code>PduR</code>.\n</li></ul>\n</li><li><strong>Segmentierter TP-Pfad (Diagnose / Large Data):</strong>\n<ul class=\"fig-list\"><li>DCM übergibt <code>DCM-I-PDU</code> (&gt; 8 Bytes bei Classic CAN) an <code>PduR</code> (<code>PduR_DcmTransmit</code>).\n</li><li><code>PduR</code> routet an TP-Modul (<code>CanTp_Transmit</code>, <code>FrTp_Transmit</code>).\n</li><li>TP segmentiert die PDU (First Frame, Flow Control, Consecutive Frames) in einzelne <code>N-PDUs</code> und übergibt diese getaktet via Interface an den Treiber. Puffer-Handling erfolgt über Callback-Abfragen (<code>PduR_ProvideTxBuffer</code> / <code>CopyTxData</code>).\n</li></ul>\n</li><li><strong>Netzwerk-Management &amp; User-Data:</strong>\n<ul class=\"fig-list\"><li>NM-Statusmaschine generiert zyklisch/eventbasiert <code>NM-PDUs</code>.\n</li><li>Optional werden <code>UserData NM-PDUs</code> synchron aus dem COM via <code>PduR</code> beigezogen und im Bus-Interface als direkte <code>NM-PDU</code> gesendet.\n</li></ul>\n</li><li><strong>CDD-Bypass:</strong>\n<ul class=\"fig-list\"><li>CDD umgeht wahlweise den COM-Stack (via <code>USER-DEFINED-I-PDU</code> über den PduR) oder den PduR komplett (via <code>USER-DEFINED-PDU</code> direkt auf Interface-Ebene), um Latenzen zu minimieren oder non-AUTOSAR-Frames zu verarbeiten.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>PDU-ID-Mapping &amp; Entkopplung:</strong> Module referenzieren PDUs über numerische Handles (<code>PduIdType</code>). Jedes Modul (<code>Com</code>, <code>PduR</code>, <code>CanIf</code>, <code>CanTp</code>) besitzt separate lokale ID-Namensräume. In der ARXML-Systembeschreibung müssen <code>SourcePduId</code> und <code>TargetPduId</code> in den PduR-Routing-Tabellen strikt aufeinander abgestimmt sein.\n</li><li><strong>PduR-Beschränkung:</strong> Der <code>PduR</code> ist zustandslos bezüglich der PDU-Payload; er transformiert, konvertiert oder verändert keine Dateninhalte, sondern routet ausschließlich Zeiger und Längen (<code>PduInfoType</code>).\n</li><li><strong>Zero-Copy &amp; Pufferarchitektur:</strong>\n<ul class=\"fig-list\"><li>Auf Interface-Ebene (<code>CanIf</code>, <code>FrIf</code>) gilt standardmäßig direkte Puffer-Referenzierung ohne Entkopplungsspeicher (ausgenommen Gateway-FIFO oder Trigger-Transmit-Puffer).\n</li><li>Bei TP-Kommunikation müssen Pufferanforderungen (<code>ProvideTxBuffer</code> / <code>CopyTxData</code>, <code>CopyRxData</code>) reentrant implementiert sein.\n</li></ul>\n</li><li><strong>IPDU-Multiplexing-Overhead:</strong> Verwendung von <code>IpduM</code> erfordert deterministisches Timing, da COM und IpduM PDU-Zustände synchronisieren müssen; Selector-Kollisionen müssen im System-Design ausgeschlossen werden.\n</li><li><strong>CDD-Entwickler-Richtlinie:</strong> Wird ein CDD unterhalb des <code>PduR</code> angebunden (<code>USER-DEFINED-PDU</code>), muss der CDD die AUTOSAR-kompatiblen Callback-Signaturen des jeweiligen Interfaces (<code>&lt;Bus&gt;If_RxIndication</code>, <code>&lt;Bus&gt;If_TxConfirmation</code>) exakt implementieren.\n</li></ul>"}, {"id": "FIG-6e1cf218cccfc105", "releases": ["R20-11", "R22-11", "R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> Architekturschichten- und Datenflussmodell (AUTOSAR Classic Platform BSW Communication Stack) mit PDU-Typisierung und Routing-Pfaden.\n</li><li><strong>Technischer Zweck &amp; funktionale Einordnung:</strong> Spezifikation des Signal- und PDU-Flusses im Kommunikations-Cluster des AUTOSAR System Templates. Das Diagramm definiert die vertikale Kapselung, die Abstraktionsebenen (Services, Hardware Abstraction, Drivers) sowie die Transformations- und Verteilungsstufen von anwendungsspezifischen Signalen über Interaktions-Layer-PDUs (I-PDUs), Netzwerk-PDUs (N-PDUs) bis hin zu Data-Link-PDUs (L-PDUs) über heterogene Bussysteme (FlexRay, CAN, LIN).\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Schichten &amp; BSW-Module (Akteure)</h5>\n<ul class=\"fig-list\"><li><strong>Application / RTE:</strong> Oberste Abstraktionsebene; Übergabe typisierter Signale (<code>Signals</code>) an den BSW-Kommunikationsstack.\n</li><li><strong>Communication Services (Service Layer):</strong>\n<ul class=\"fig-list\"><li><code>AUTOSAR COM</code>: Signal-to-PDU-Mapping, Signal-Packing/Unpacking, Signal-Filterung, Cyclic/Event-basiertes Senden.\n</li><li><code>IPDU multiplexer (IpduM)</code>: Multiplexen/Demultiplexen dynamischer PDU-Layouts sowie Container-PDU-Handling.\n</li><li><code>SecOC (Secure Onboard Communication)</code>: Kryptografische Absicherung von PDUs (Authentifizierung und Frischeprüfung); angebunden an den <code>PDU Router</code>.\n</li><li><code>Diagnostic Communication Manager (DCM)</code>: Verarbeitung von UDS-/OBD-Diagnoseanfragen; Bereitstellung/Empfang von <code>DCM-I-PDU</code>.\n</li><li><code>PDU Router (PduR)</code>: Zentraler, protokollunabhängiger Routing-Knotenpunkt für I-PDUs (1:1, 1:n, Gateway-Routing zwischen TPs, Interfaces, SecOC und IpduM).\n</li><li><code>Complex Device Driver (CDD)</code>: Bypass- und Spezialmodule; oberer CDD nutzt <code>USER-DEFINED-I-PDU</code>, unterer CDD bindet direkt über <code>USER-DEFINED-PDU</code> an Interfaces an.\n</li><li><code>Network Management (NM Module)</code>: Generische/busspezifische NM-Module (<code>FrNm</code>, <code>CanNm</code>, <code>LinNm</code>); aggregiert <code>NM-PDU</code> und nimmt <code>UserData NM-PDU</code> auf.\n</li><li><strong>Transportprotokoll-Module:</strong> <code>FlexRay Tp (FrTp)</code>, <code>CAN Tp (CanTp)</code>, <code>J1939Tp</code>; Segmentierung/Reassemblierung größerer I-PDUs in N-PDUs.\n</li></ul>\n</li><li><strong>Communication HW Abstraction:</strong>\n<ul class=\"fig-list\"><li><code>FlexRay Interface (FrIf)</code>, <code>CAN Interface (CanIf)</code>, <code>LIN Interface (LinIf, incl. LIN TP)</code>: Abstraktion der Controller/Transceiver-Hardware, PDU-Kanalzuordnung und PDU-ID-Übersetzung.\n</li></ul>\n</li><li><strong>Communication Drivers (MCAL Layer):</strong>\n<ul class=\"fig-list\"><li><code>FlexRay Driver (Fr)</code>, <code>CAN Driver (Can)</code>, <code>LIN Low Level Driver (Lin)</code>: Direkte Hardware-Register-Ansteuerung und Mailbox-Handling.\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">PDU-Klassifikationen &amp; Stereotypen (System Template / Metamodell)</h5>\n<ul class=\"fig-list\"><li><code>Signals</code>: Rohdaten-Payloads der Software Components (SWCs) an der RTE-Schnittstelle.\n</li><li><code>I-SIGNAL-I-PDU</code>: PDU-Container zur Bündelung von <code>ISignal</code> und <code>ISignalGroup</code>; Schnittstelle zwischen COM, PDU Router, IpduM und SecOC.\n</li><li><code>CONTAINER-I-PDU</code>: PDU-Container zur Bündelung mehrerer PDUs für Transport und Multiplexing via IpduM.\n</li><li><code>MULTIPLEXED-I-PDU</code>: Gesamte PDU nach Zusammenbau durch <code>IpduM</code> (statischer Anteil + Multiplex-Payload).\n</li><li><code>SECURED-I-PDU</code>: Durch SecOC kryptografisch geschützte PDU (Payload inklusive Authentifikationsinformation / MAC und Freshness Value).\n</li><li><code>DCM-I-PDU</code>: Unsegmentierte Diagnose-Payloads (UDS-Frames).\n</li><li><code>UserData NM-PDU</code>: Payload-Daten aus dem COM, die in die Netzwerk-Management-Nachricht eingebettet werden.\n</li><li><code>I-PDU</code>: Interaktionsschicht-PDU; neutrale Transporteinheit auf <code>PduR</code>-Ebene.\n</li><li><code>N-PDU</code>: Network-PDU; segmentierte Transportprotokoll-Einheiten (FrTp, CanTp, J1939Tp).\n</li><li><code>NM-PDU</code>: Management-Frames der NM-State-Machine, direkt in Hardware-Interfaces gespeist.\n</li><li><code>USER-DEFINED-I-PDU</code> / <code>USER-DEFINED-PDU</code>: Proprietäre oder zeitkritische PDU-Formate für CDD-Anbindungen.\n</li><li><code>L-PDU</code>: Link-Layer-PDU (Hardware-Frame, z. B. CAN-Frame mit CAN-ID und DLC) zwischen Interface und MCAL-Treiber.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<h5 class=\"fig-section-h5\">Transmit-Pfade (TX)</h5>\n<ol class=\"fig-list\"><li><strong>Unsegmentierter Standard-Signalpfad:</strong>\n<ul class=\"fig-list\"><li>RTE übergibt Signalwerte an <code>AUTOSAR COM</code> (<code>Com_SendSignal</code>).\n</li><li>COM packt Signale in die zugehörige <code>I-SIGNAL-I-PDU</code> und triggert den <code>PduR</code> (<code>PduR_ComTransmit</code>).\n</li><li><code>PduR</code> leitet die <code>I-PDU</code> deterministisch an das Ziel-Interface weiter (z. B. <code>CanIf_Transmit</code>).\n</li><li>Das Interface kapselt die Payload in eine <code>L-PDU</code> und übergibt an den Treiber (<code>Can_Write</code>).\n</li><li>Rückmeldung erfolgt asynchron über Tx-Confirmation-Callbacks von MCAL über Interface und PduR bis COM.\n</li></ul>\n</li><li><strong>Multiplex-Pfad (IpduM):</strong>\n<ul class=\"fig-list\"><li>COM separiert statische und dynamische Signale; dynamische Teile gehen als <code>I-SIGNAL-I-PDU (Multiplexed part)</code> an <code>IpduM</code>.\n</li><li><code>IpduM</code> kombiniert den Selektor-Wert mit dem entsprechenden dynamischen Signal-Layout zu einer <code>MULTIPLEXED-I-PDU</code> und übergibt an <code>PduR</code>.\n</li></ul>\n</li><li><strong>Segmentierter TP-Pfad (Diagnose / Large Data):</strong>\n<ul class=\"fig-list\"><li>DCM übergibt <code>DCM-I-PDU</code> (&gt; 8 Bytes bei Classic CAN) an <code>PduR</code> (<code>PduR_DcmTransmit</code>).\n</li><li><code>PduR</code> routet an TP-Modul (<code>CanTp_Transmit</code>, <code>FrTp_Transmit</code>).\n</li><li>TP segmentiert die PDU (First Frame, Flow Control, Consecutive Frames) in einzelne <code>N-PDUs</code> und übergibt diese getaktet via Interface an den Treiber. Puffer-Handling erfolgt über Callback-Abfragen (<code>PduR_ProvideTxBuffer</code> / <code>CopyTxData</code>).\n</li></ul>\n</li><li><strong>Netzwerk-Management &amp; User-Data:</strong>\n<ul class=\"fig-list\"><li>NM-Statusmaschine generiert zyklisch/eventbasiert <code>NM-PDUs</code>.\n</li><li>Optional werden <code>UserData NM-PDUs</code> synchron aus dem COM via <code>PduR</code> beigezogen und im Bus-Interface als direkte <code>NM-PDU</code> gesendet.\n</li></ul>\n</li><li><strong>CDD-Bypass:</strong>\n<ul class=\"fig-list\"><li>CDD umgeht wahlweise den COM-Stack (via <code>USER-DEFINED-I-PDU</code> über den PduR) oder den PduR komplett (via <code>USER-DEFINED-PDU</code> direkt auf Interface-Ebene), um Latenzen zu minimieren oder non-AUTOSAR-Frames zu verarbeiten.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>PDU-ID-Mapping &amp; Entkopplung:</strong> Module referenzieren PDUs über numerische Handles (<code>PduIdType</code>). Jedes Modul (<code>Com</code>, <code>PduR</code>, <code>CanIf</code>, <code>CanTp</code>) besitzt separate lokale ID-Namensräume. In der ARXML-Systembeschreibung müssen <code>SourcePduId</code> und <code>TargetPduId</code> in den PduR-Routing-Tabellen strikt aufeinander abgestimmt sein.\n</li><li><strong>PduR-Beschränkung:</strong> Der <code>PduR</code> ist zustandslos bezüglich der PDU-Payload; er transformiert, konvertiert oder verändert keine Dateninhalte, sondern routet ausschließlich Zeiger und Längen (<code>PduInfoType</code>).\n</li><li><strong>Zero-Copy &amp; Pufferarchitektur:</strong>\n<ul class=\"fig-list\"><li>Auf Interface-Ebene (<code>CanIf</code>, <code>FrIf</code>) gilt standardmäßig direkte Puffer-Referenzierung ohne Entkopplungsspeicher (ausgenommen Gateway-FIFO oder Trigger-Transmit-Puffer).\n</li><li>Bei TP-Kommunikation müssen Pufferanforderungen (<code>ProvideTxBuffer</code> / <code>CopyTxData</code>, <code>CopyRxData</code>) reentrant implementiert sein.\n</li></ul>\n</li><li><strong>IPDU-Multiplexing-Overhead:</strong> Verwendung von <code>IpduM</code> erfordert deterministisches Timing, da COM und IpduM PDU-Zustände synchronisieren müssen; Selector-Kollisionen müssen im System-Design ausgeschlossen werden.\n</li><li><strong>CDD-Entwickler-Richtlinie:</strong> Wird ein CDD unterhalb des <code>PduR</code> angebunden (<code>USER-DEFINED-PDU</code>), muss der CDD die AUTOSAR-kompatiblen Callback-Signaturen des jeweiligen Interfaces (<code>&lt;Bus&gt;If_RxIndication</code>, <code>&lt;Bus&gt;If_TxConfirmation</code>) exakt implementieren.\n</li></ul>"}], "trans": [{"from": "FIG-4ef6e22a900b8c92", "to": "FIG-abe1d38b0d5f1fa2", "fr": "R3.2.3", "tr": "R4.0.3", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Gesamtdiagramm: Neu-Rendering mit veränderter Skalierung und Bildabmessungen (870x566 zu 887x577 Pixel).\n</li><li>Schriftbild: Subtile typografische Anpassungen der Beschriftungen ohne inhaltliche Text- oder Strukturänderungen.\n</li></ul>"}, {"from": "FIG-abe1d38b0d5f1fa2", "to": "FIG-4ef6e22a900b8c92", "fr": "R4.0.3", "tr": "R4.1.3", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Gesamtdiagramm: Rückkehr zum ursprünglichen Rendering und Seitenverhältnis (887x577 zu 870x566 Pixel).\n</li></ul>"}, {"from": "FIG-4ef6e22a900b8c92", "to": "FIG-adbd9d3506f20d83", "fr": "R4.1.3", "tr": "R4.2.2", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Modul <code>IPDU multiplexer</code>: Verbindung <code>I-SIGNAL-I-PDU (Multiplexed part)</code> umbenannt zu <code>CONTAINER-I-PDU</code> (bidirektionaler Pfeil zum <code>PDU Router</code>).\n</li><li>Modul <code>SecOC</code>: BSW-Modul im Service Layer neu hinzugefügt, angebunden an den <code>PDU Router</code> über <code>I-SIGNAL-I-PDU</code> und <code>SECURED-I-PDU</code> (beide bidirektional).\n</li></ul>"}, {"from": "FIG-adbd9d3506f20d83", "to": "FIG-3d188c2c028eaf2c", "fr": "R4.2.2", "tr": "R4.3.1", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-3d188c2c028eaf2c", "to": "FIG-6e1cf218cccfc105", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-6e1cf218cccfc105", "to": "FIG-adbd9d3506f20d83", "fr": "R23-11", "tr": "R24-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
